// Calculate return metrics
const order = $json.order || {};
const createdDate = new Date(order.created_at);
const now = new Date();
const daysSinceOrder = Math.floor((now - createdDate) / (1000 * 60 * 60 * 24));

return {
  json: {
    order_id: order.id,
    customer_id: order.customer ? order.customer.id : null,
    order_value: parseFloat(order.total_price || 0),
    days_since_order: daysSinceOrder,
    total_previous_orders: order.customer ? order.customer.orders_count : 1,
    return_reason: $('Return Request Webhook1').item.json.body.reason
  }
};
